{"cards": [{"node_code": "N_61854b6fa0b192f4", "definition": "研究常规切削加工中切削速度、进给量、背吃刀量等工艺参数的选择原则，切削力产生的工程应用及切削液、工件装夹等加工条件的确定方法。", "boundary": "聚焦于工艺规划层面的参数设定与条件控制，旨在优化加工效率、刀具寿命及表面质量。边界在于侧重工程经验、查表法及基于宏观现象的参数优化，不涉及切削力与温度场的微观物理机理推导（归入“金属切削机理”）或切削热传递的深层理论分析（归入“机械加工方法、切削热与切屑控制”）。", "includes": ["切削三要素（速度、进给、吃刀量）的选择与优化", "切削力在机床功率计算、夹具设计及振动分析中的应用", "切削液类型选择、工件装夹方式及加工环境条件控制"], "excludes": ["切削力与温度场的微观物理机理及理论模型推导", "切削热传递的深层理论分析及切屑形成的物理过程"], "sibling_distinctions": [{"other_code": "N_ab3b4de7fcbf8b15", "rule": "本节点关注工艺参数的工程选择与切削力的宏观应用，兄弟节点关注切削热、切屑形成的物理过程及控制方法。"}, {"other_code": "N_f61a6142a9aebbc5", "rule": "本节点关注适用于多种切削方式的通用参数与条件，兄弟节点关注车、镗、钻等特定加工方法的工艺细节。"}], "cross_boundary_rule": "若研究重点在于参数对加工结果的影响规律及工程选择，主挂载本节点；若重点在于切削力/热产生的物理机理，主挂载“金属切削机理”或“机械加工方法、切削热与切屑控制”。"}, {"node_code": "N_431a31ffb145d0f7", "definition": "研究利用样板、靠模或数控轨迹控制刀具运动，以加工出特定轮廓、曲面或复杂形状零件的仿形与成形切削工艺方法。", "boundary": "涵盖机械仿形、光学仿形及数控成形加工，重点在于刀具轨迹规划、靠模设计、仿形机构原理及复杂曲面的加工策略。边界在于聚焦于“形状生成”的工艺方法，不涉及具体切削参数优化（归入“切削参数、切削力与加工条件”）或特定机床（如车床）的常规操作（归入“车削、镗削与钻削”）。", "includes": ["机械与光学仿形加工原理、靠模设计与仿形机构", "数控成形加工中的刀具轨迹规划与曲面加工策略", "复杂轮廓、型腔及自由曲面的成形切削工艺"], "excludes": ["通用切削参数的选择与优化", "特定机床（如车床、铣床）的常规操作与基础工艺"], "sibling_distinctions": [{"other_code": "N_f61a6142a9aebbc5", "rule": "本节点关注基于轨迹或靠模的复杂形状生成工艺，兄弟节点关注车、镗、钻等特定加工方法的基础工艺。"}, {"other_code": "N_61854b6fa0b192f4", "rule": "本节点关注形状生成的工艺方法与轨迹规划，兄弟节点关注切削参数、切削力及加工条件的通用选择。"}], "cross_boundary_rule": "若研究重点在于复杂轮廓/曲面的轨迹规划、靠模设计或仿形机构，主挂载本节点；若重点在于通用切削参数优化或特定机床的基础操作，主挂载相应兄弟节点。"}, {"node_code": "N_ab3b4de7fcbf8b15", "definition": "研究常规切削加工中切削热的产生与传递规律、切屑的形成机理与控制方法，以及不同机械加工方法对热-力耦合过程的影响。", "boundary": "聚焦于切削过程中的热物理现象与切屑行为，旨在通过控制切削热和切屑形态来改善加工质量、刀具寿命及安全性。边界在于侧重工程层面的热控制与切屑管理，不涉及切削力/温度场的深层微观物理机理推导（归入“金属切削机理”）或通用切削参数的工程选择（归入“切削参数、切削力与加工条件”）。", "includes": ["切削热产生机理、热传递规律及切削区温度场控制", "切屑形成过程、切屑形态（连续、节状、崩碎）及其控制方法", "不同机械加工方法（如高速切削、干切削）对热-力耦合过程的影响"], "excludes": ["切削力与温度场的微观物理机理及理论模型推导", "通用切削参数（速度、进给、吃刀量）的工程选择与优化"], "sibling_distinctions": [{"other_code": "N_61854b6fa0b192f4", "rule": "本节点关注切削热与切屑的物理过程及控制，兄弟节点关注切削参数的工程选择与切削力的宏观应用。"}, {"other_code": "N_f61a6142a9aebbc5", "rule": "本节点关注适用于多种切削方式的热-切屑通用规律，兄弟节点关注车、镗、钻等特定加工方法的工艺细节。"}], "cross_boundary_rule": "若研究重点在于切削热传递、切屑形态控制或热-力耦合的工程影响，主挂载本节点；若重点在于切削力/温度场的微观物理机理，主挂载“金属切削机理”；若重点在于通用参数选择，主挂载“切削参数、切削力与加工条件”。"}]}
